// Credits are earned through play. No purchases, payments or real-money items.
const ARMOUR_ITEMS=[{id:'none',name:'Classic outfit',level:1,cost:0,hp:0},{id:'trail',name:'Trail Vest',level:1,cost:250,hp:1},{id:'ranger',name:'Ranger Plate',level:10,cost:900,hp:2},{id:'nova',name:'Nova Suit',level:25,cost:2200,hp:4},{id:'cosmic',name:'Cosmic Mail',level:45,cost:4500,hp:6}];
const SHIELD_ITEMS=[{id:'none',name:'No shield',level:1,cost:0,capacity:0},{id:'leaf',name:'Leaf Shield',level:1,cost:200,capacity:1},{id:'ranger',name:'Ranger Shield',level:10,cost:800,capacity:2},{id:'prism',name:'Prism Shield',level:25,cost:2000,capacity:4},{id:'cosmic',name:'Cosmic Shield',level:45,cost:4200,capacity:6}];
const STYLE_PACKS=[{id:'none',name:'Your own style',level:1,cost:0,colour:'#d5fa59',icon:'✦'},{id:'trail',name:'Trailblazer Crest',level:5,cost:400,colour:'#a7e9ce',icon:'◆'},{id:'neon',name:'Neon Explorer',level:15,cost:1200,colour:'#a7c8ff',icon:'⌁'},{id:'scholar',name:'Scholar Knight',level:25,cost:2400,colour:'#d4b1ff',icon:'✧'},{id:'galaxy',name:'Galaxy Guardian',level:40,cost:4000,colour:'#ffcda8',icon:'☾'},{id:'legend',name:'Level 50 Legend',level:50,cost:6000,colour:'#fff2a4',icon:'✦'}];
function shopInventory(){if(!profile.inventory||typeof profile.inventory!=='object'||Array.isArray(profile.inventory))profile.inventory={};profile.equipment??={armour:'none',shield:'none'};return profile.inventory}
function validEquipment(kind,id,level=playerLevel()){const list=kind==='armour'?ARMOUR_ITEMS:SHIELD_ITEMS;return list.find(i=>i.id===id&&level>=i.level)||list[0]}
function ownedEquipment(kind,id){return id==='none'||!!shopInventory()[kind+':'+id]}
function equippedItems(){shopInventory();return{armour:ownedEquipment('armour',profile.equipment.armour)?profile.equipment.armour:'none',shield:ownedEquipment('shield',profile.equipment.shield)?profile.equipment.shield:'none'}}
function equipmentForPeer(p){return{armour:p.state?.armour||p.armour||'none',shield:p.state?.shield||p.shieldItem||'none'}}
const plainBattleHero=getBattleHero;getBattleHero=function(id=profile.hero,level=playerLevel(),equipment=equippedItems()){const h=plainBattleHero(id,level),armour=validEquipment('armour',equipment?.armour,level),shield=validEquipment('shield',equipment?.shield,level);return{...h,hp:h.hp+armour.hp,armour:armour.id,shieldItem:shield.id,shieldMax:shield.capacity}};
const plainLookSanitiser=sanitiseLook;sanitiseLook=function(value){return{...plainLookSanitiser(value),pack:STYLE_PACKS.some(p=>p.id===value?.pack)?value.pack:'none'}};
const unadornedHeroSVG=heroSVG;heroSVG=function(id=profile.hero,extra='',look,weapon,equipment){const svg=unadornedHeroSVG(id,extra,look,weapon),pack=STYLE_PACKS.find(p=>p.id===(look||lookFor(id)).pack);const eq=equipment||{...equippedItems(),level:playerLevel()},armour=validEquipment('armour',eq.armour,eq.level||playerLevel()),shield=validEquipment('shield',eq.shield,eq.level||playerLevel()),metal={trail:'#9eb6a0',ranger:'#90b9ca',nova:'#b7a0d9',cosmic:'#e5cf8a'},armourArt=armour.id==='none'?'':`<path d="M80 150L111 162 143 150 149 180 130 195 91 195 73 180Z" fill="${metal[armour.id]}" stroke="#394254" stroke-width="4"/><path d="M89 165L111 175 134 164" fill="none" stroke="#f1ead9" stroke-width="3"/>`,shieldArt=shield.id==='none'?'':`<path d="M20 164L43 155 66 164 62 191 43 208 24 191Z" fill="${shield.id==='cosmic'?'#e8d38a':shield.id==='prism'?'#bb9fdf':'#9fceb9'}" stroke="#343d50" stroke-width="4"/><path d="M43 164L51 179 43 192 35 179Z" fill="#f4f1cf"/>`;const equippedSVG=svg.replace('</svg>',(typeof detailedEquipmentArt==='function'?detailedEquipmentArt({armour:armour.id,shield:shield.id}):armourArt+shieldArt)+'</svg>');if(!pack||pack.id==='none')return equippedSVG;return equippedSVG.replace('</svg>',`<g data-style-pack="${pack.id}"><path d="M97 159L111 151 125 159 122 176 111 185 100 176Z" fill="${pack.colour}" stroke="#35354e" stroke-width="3"/><text x="111" y="174" text-anchor="middle" font-size="14" fill="#3e3b56">${pack.icon}</text><path d="M72 145L60 157M151 145L163 157" stroke="${pack.colour}" stroke-width="7" stroke-linecap="round"/>${pack.id==='legend'?'<path d="M40 51l4 8 9 4-9 4-4 8-4-8-9-4 9-4M179 44l4 8 9 4-9 4-4 8-4-8-9-4 9-4" fill="#fff0a5"/>':''}</g></svg>`)};
function creditShop(tab='armour'){if(live){toast('Leave the live room before changing purchased equipment.');return}shopInventory();const tabs=['armour','shield','style'],lists={armour:ARMOUR_ITEMS,shield:SHIELD_ITEMS,style:STYLE_PACKS};openModal(`${topModal('QUEST CREDIT SHOP')}<h2 id="modal-title">Earn it. Make it yours.</h2><p class="shop-balance">◆ <b>${profile.coins}</b> credits · Level ${playerLevel()} / 50</p><p class="sub">Earn credits by learning and clearing game levels. Equipment effects start with your next run. There are no real-money purchases.</p><div class="shop-tabs">${tabs.map(t=>`<button data-shop-tab="${t}" aria-pressed="${tab===t}">${{armour:'Armour',shield:'Shields',style:'Level looks'}[t]}</button>`).join('')}</div><div class="shop-grid">${lists[tab].map(item=>{const key=tab+':'+item.id,owned=item.id==='none'||!!profile.inventory[key],equipped=tab==='style'?(lookFor().pack||'none')===item.id:equippedItems()[tab]===item.id,locked=playerLevel()<item.level;return `<article class="shop-item ${equipped?'equipped':''}"><div class="shop-item-icon" style="color:${item.colour||'#bde5d6'}">${tab==='armour'?'♜':tab==='shield'?'⬟':item.icon}</div><h3>${item.name}</h3><p>${tab==='armour'?`+${item.hp} base hearts`:tab==='shield'?`${item.capacity} shield capacity · recharges after 14 seconds without a hit`:'A unique crest and accents for your selected companion'}</p><small>LEVEL ${item.level} · ${owned?'OWNED':item.cost+' CREDITS'}</small><button class="${equipped?'secondary':'primary'}" data-shop-item="${key}" ${locked||equipped||(!owned&&profile.coins<item.cost)?'disabled':''}>${locked?'🔒 Level '+item.level:equipped?'Equipped ✓':owned?'Equip':'Unlock · '+item.cost}</button></article>`}).join('')}</div><div class="bonus-guide"><h3>How credits and bonuses work</h3><p>Correct answer: 10 XP + 5 credits.<br>Correct within 30 seconds: +5 XP +3 credits, for each question.<br>10/10 correct: +25 XP +25 credits.<br>All ten correct within 30 seconds each: another +25 XP +25 credits.<br>Clear a game level: 1 score point = 1 credit.</p></div><button class="secondary" data-custom="hub">Back to my setup</button>`)}
function buyOrEquip(key){if(live)return;const[kind,id]=key.split(':'),list=kind==='armour'?ARMOUR_ITEMS:kind==='shield'?SHIELD_ITEMS:kind==='style'?STYLE_PACKS:null,item=list?.find(i=>i.id===id);if(!item||playerLevel()<item.level)return;shopInventory();if(id!=='none'&&!profile.inventory[key]){if(profile.coins<item.cost){toast('Earn more credits to unlock this item.');return}profile.coins-=item.cost;profile.inventory[key]=true}if(kind==='style'){profile.avatarLooks??={};profile.avatarLooks[profile.hero]={...lookFor(),pack:item.id};avatarSprites.clear()}else profile.equipment[kind]=item.id;save();creditShop(kind);GameAudio.effect('unlock')}
const rewardPreparation=buildPreparation;buildPreparation=function(subject){const q=rewardPreparation(subject);q.fastAnswers=0;q.rewardDone=false;return q};
const timedAnswerReward=answer;answer=function(n){if(!quiz||quiz.answered)return;const qref=quiz,correct=n>=0&&qref.options[n]?.i===qref.item.q[2],elapsed=Math.max(0,Date.now()-(qref.startedAt??Date.now()));timedAnswerReward(n);if(correct&&elapsed<=30000){qref.fastAnswers=(qref.fastAnswers||0)+1;profile.xp+=5;profile.coins+=3;save();document.querySelector('#answer-feedback')?.insertAdjacentHTML('beforeend','<div class="speed-bonus">⚡ Under 30 seconds · +5 XP · +3 credits</div>')}};
function awardQuizCompletion(q){if(!q||q.rewardDone||q.deck.length!==10)return;q.rewardDone=true;let xp=0,credits=0;const lines=[];if(q.right===10){xp+=25;credits+=25;lines.push('Perfect 10/10 · +25 XP · +25 credits')}if(q.right===10&&q.fastAnswers===10){xp+=25;credits+=25;lines.push('Ten fast correct answers · +25 XP · +25 credits')}profile.xp+=xp;profile.coins+=credits;save();return{xp,credits,fast:q.fastAnswers||0,lines}}
const rewardedPreparationResults=preparationResults;preparationResults=function(){const rewards=awardQuizCompletion(quiz);rewardedPreparationResults();if(rewards&&!live)document.querySelector('.loadout-results')?.insertAdjacentHTML('afterbegin',`<div class="round-bonuses"><h3>Your learning bonuses</h3><p>${rewards.fast}/10 correct answers within 30 seconds · ${rewards.fast*5} extra XP · ${rewards.fast*3} extra credits</p>${rewards.lines.map(s=>'<p>'+s+'</p>').join('')}</div>`)};
const rewardedPractice=practiceResults;practiceResults=function(){const rewards=awardQuizCompletion(quiz);rewardedPractice();if(rewards)document.querySelector('.results')?.insertAdjacentHTML('beforeend',`<div class="round-bonuses">${rewards.fast} fast correct answers · ${rewards.fast*3} speed credits${rewards.lines.map(s=>'<p>'+s+'</p>').join('')}</div>`)};
const shieldedChallenge=initialiseChallenge;initialiseChallenge=function(g){shieldedChallenge(g);g.shieldMax=g.hero.shieldMax||0;g.shieldCharge=g.shieldMax;g.shieldClock=0};
function rechargeShield(p,dt){if(!p.shieldMax||p.hp<=0)return;p.shieldClock=(p.shieldClock||0)+dt;if(p.shieldClock>=14){p.shieldCharge=p.shieldMax;p.shieldClock=0}}
function absorbShield(p,damage){p.shieldClock=0;const absorb=Math.min(p.shieldCharge||0,damage);p.shieldCharge=Math.max(0,(p.shieldCharge||0)-absorb);return damage-absorb}
const unshieldedDamage=damagePlayer;damagePlayer=function(g){if(g.invincible>0)return;const original=g.monsterDamage,left=absorbShield(g,original);if(left===0){g.invincible=1.05;GameAudio.effect('pickup');return}g.monsterDamage=left;unshieldedDamage(g);g.monsterDamage=original};
const rawMiniDamage=miniDamage;miniDamage=function(g,amount=1){if(g.invincible>0)return;const left=absorbShield(g,amount);if(left)rawMiniDamage(g,left);else{g.invincible=1.2;GameAudio.effect('pickup')}};
liveHurt=function(p){if(p.inv>0||p.hp<=0)return;const left=absorbShield(p,game.monsterDamage);p.hp=Math.max(0,p.hp-left);p.inv=1.1;if(p.id===live.selfId)GameAudio.effect(left?'hurt':'pickup')};
const shieldUpdate=updateArena;updateArena=function(dt){if(game)rechargeShield(game,dt);if(live?.host&&live.units)Object.values(live.units).forEach(p=>rechargeShield(p,dt));return shieldUpdate(dt)};
const shieldRender=drawBreedAvatar;drawBreedAvatar=function(c,g){const ok=shieldRender(c,g);if(g.shieldCharge>0){c.strokeStyle='#b9f7ff99';c.lineWidth=3;c.beginPath();c.ellipse(g.x,g.y-13,44,56,0,0,7);c.stroke()}return ok};
const equipmentConnect=connectLive;connectLive=function(data,host){equipmentConnect(data,host);if(live)Object.assign(live.state,equippedItems())};
const creditHub=personalHub;personalHub=function(){creditHub();document.querySelector('.setup-actions')?.insertAdjacentHTML('beforeend','<button class="secondary" data-shop-tab="armour">◆ Credit shop · Armour, shields & level looks</button>')};
const creditHome=home;home=function(){return creditHome().replace('<button class="secondary" data-custom="weapons">ϟ Weapons</button>','<button class="secondary" data-custom="weapons">ϟ Weapons</button><button class="secondary" data-shop-tab="armour">◆ Credit shop</button>')};
const arenaClearPoints=showMatchResults;showMatchResults=function(win){const g=game;if(!g)return;const score=g.kills*30+g.questionsRight*40+(win?200+Math.ceil(g.time)*2:0);if(win)profile.coins+=score-g.mode.coins;arenaClearPoints(win);document.querySelector('.pro-results')?.insertAdjacentHTML('beforeend',`<div class="clear-credit">${win?'+ '+score+' LEVEL-CLEAR CREDITS':'Question credits are saved.'}<small>1 score point = 1 credit on a clear. Question bonuses are separate.</small></div>`)};
const liveClearPoints=showLiveResults;showLiveResults=function(win){if(!live||live.ended)return;const g=game,score=Math.floor((g?.kills||0)*30+(g?.questionsRight||0)*40+(win?200+Math.ceil(g?.time||0)*2:0));if(win)profile.coins+=score-selectedMode().coins;liveClearPoints(win);document.querySelector('.results')?.insertAdjacentHTML('beforeend',`<div class="clear-credit">${score} SCORE POINTS · +${win?score:0} LEVEL-CLEAR CREDITS<small>1 point = 1 credit when your crew clears the level.</small></div>`)};
const shieldHUD=renderArena;renderArena=function(g){shieldHUD(g);let badge=document.querySelector('#shield-hud');if(!badge){document.querySelector('.health-hud')?.insertAdjacentHTML('beforeend','<small id="shield-hud"></small>');badge=document.querySelector('#shield-hud')}if(badge)badge.textContent=g.shieldMax?'⬟ '+(g.shieldCharge||0)+' / '+g.shieldMax+' SHIELD':''};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.shopTab){e.stopImmediatePropagation();creditShop(b.dataset.shopTab)}if(b.dataset.shopItem){e.stopImmediatePropagation();buyOrEquip(b.dataset.shopItem)}},true);
shopInventory();updateBar();if(!window.location.hash.startsWith('#room=')&&!window.location.hash.startsWith('#challenge='))navigate('home');
